import{branches,cds,commands,ranks,uniforms,equipment}from"./data.js";import{TabNav}from"./components/TabNav.js";import{BranchOverview}from"./components/BranchOverview.js";import{CommandGrid}from"./components/CommandGrid.js";import{RankTable}from"./components/RankTable.js";import{UniformShowcase}from"./components/UniformShowcase.js";import{EquipmentGrid}from"./components/EquipmentGrid.js";import{CDSSection}from"./components/CDSSection.js";const TABS=[{id:"overview",label:"Overview"},{id:"army",label:"Army"},{id:"navy",label:"Navy"},{id:"airforce",label:"Air Force"},{id:"cds",label:"CDS"},{id:"commands",label:"Commands"},{id:"ranks",label:"Ranks"},{id:"uniforms",label:"Uniforms"},{id:"equipment",label:"Equipment"}];let activeTab="overview",commandFilter="All",rankService="army",equipmentFilter="All";function renderTabNav(){document.getElementById("tab-nav-root").innerHTML=TabNav(TABS,activeTab)}function renderContent(){const n=document.getElementById("tab-content-root");n.style.opacity="0",setTimeout(()=>{n.innerHTML=getTabContent(activeTab),attachTabListeners(),n.style.opacity="1"},150)}function getTabContent(n){switch(n){case"overview":return BranchOverview(branches);case"army":case"navy":case"airforce":return renderBranchDetail(n);case"cds":return CDSSection(cds);case"commands":return renderCommandsTab();case"ranks":return renderRanksTab();case"uniforms":return UniformShowcase(uniforms);case"equipment":return renderEquipmentTab();default:return""}}function renderBranchDetail(n){const e=branches.find(e=>e.id===n);if(!e)return"";const t=e.keyFacts.map(n=>`<li>${n}</li>`).join(""),a=e.notableOperations.map(n=>`<li>${n}</li>`).join(""),r=ranks[n]||[],i={};r.forEach(n=>{i[n.grade]||(i[n.grade]=[]),i[n.grade].push(n)});const s=Object.entries(i).map(([n,e])=>`\n            <div class="branch-rank-group">\n                <h4>${n}</h4>\n                <table class="rank-table compact">\n                    <thead><tr><th>Rank</th><th>Abbr.</th><th>Pay Level</th><th>Description</th></tr></thead>\n                    <tbody>${e.map(n=>`\n            <tr>\n                <td>${n.rank}</td>\n                <td>${n.abbr}</td>\n                <td>${n.payLevel}</td>\n                <td>${n.description}</td>\n            </tr>\n        `).join("")}</tbody>\n                </table>\n            </div>\n        `).join(""),c=equipment.filter(n=>n.service===e.name.split(" ").pop()||"All"===n.service||n.service.includes(e.name.split(" ").pop())),o=c.length>0?c.map(n=>`\n        <div class="branch-equip-item">\n            <strong>${n.name}</strong> — ${n.type} <span class="equip-origin-badge">${n.origin}</span>\n            <p>${n.description}</p>\n        </div>\n    `).join(""):'<p class="no-results">No specific equipment listed.</p>';return`\n        <div class="branch-detail" style="--branch-color: ${e.color}">\n            <div class="branch-detail-header" style="background: ${e.color}">\n                <div class="branch-detail-emblem">${e.name.split(" ").map(n=>n[0]).join("")}</div>\n                <div>\n                    <h2>${e.name}</h2>\n                    <p class="branch-detail-motto">"${e.motto}"</p>\n                </div>\n            </div>\n            <div class="branch-detail-body">\n                <div class="branch-info-grid">\n                    <div class="info-card">\n                        <span class="info-label">Chief</span>\n                        <span class="info-value">${e.chief}</span>\n                        <span class="info-sub">Since ${e.chiefSince}</span>\n                    </div>\n                    <div class="info-card">\n                        <span class="info-label">Strength</span>\n                        <span class="info-value">${e.strength}</span>\n                    </div>\n                    <div class="info-card">\n                        <span class="info-label">Founded</span>\n                        <span class="info-value">${e.founded}</span>\n                    </div>\n                    <div class="info-card">\n                        <span class="info-label">Headquarters</span>\n                        <span class="info-value">${e.hq}</span>\n                    </div>\n                </div>\n\n                <p class="branch-full-overview">${e.overview}</p>\n\n                <div class="branch-section">\n                    <h3>Role & Responsibilities</h3>\n                    <p>${e.role}</p>\n                </div>\n\n                <div class="branch-section">\n                    <h3>Key Facts</h3>\n                    <ul class="branch-facts-list">${t}</ul>\n                </div>\n\n                <div class="branch-section">\n                    <h3>Notable Operations</h3>\n                    <ol class="branch-ops-list">${a}</ol>\n                </div>\n\n                <div class="branch-section">\n                    <h3>Rank Structure</h3>\n                    ${s}\n                </div>\n\n                <div class="branch-section">\n                    <h3>Key Equipment</h3>\n                    ${o}\n                </div>\n            </div>\n        </div>\n    `}function renderCommandsTab(){return`\n        <div class="command-filter-bar">\n            <button class="cmd-filter-btn ${"All"===commandFilter?"active":""}" data-filter="All">All</button>\n            <button class="cmd-filter-btn ${"Army"===commandFilter?"active":""}" data-filter="Army">Army</button>\n            <button class="cmd-filter-btn ${"Navy"===commandFilter?"active":""}" data-filter="Navy">Navy</button>\n            <button class="cmd-filter-btn ${"Air Force"===commandFilter?"active":""}" data-filter="Air Force">Air Force</button>\n        </div>\n    `+CommandGrid(commands,commandFilter)}function renderRanksTab(){return`\n        <div class="rank-filter-bar">\n            <button class="rank-filter-btn ${"army"===rankService?"active":""}" data-service="army">Army</button>\n            <button class="rank-filter-btn ${"navy"===rankService?"active":""}" data-service="navy">Navy</button>\n            <button class="rank-filter-btn ${"airforce"===rankService?"active":""}" data-service="airforce">Air Force</button>\n        </div>\n    `+RankTable(ranks,rankService)}function renderEquipmentTab(){return`\n        <div class="equipment-filter-bar">\n            <button class="equip-filter-btn ${"All"===equipmentFilter?"active":""}" data-equip-filter="All">All</button>\n        </div>\n    `+EquipmentGrid(equipment,equipmentFilter)}function attachTabListeners(){document.querySelectorAll(".cmd-filter-btn").forEach(n=>{n.addEventListener("click",()=>{commandFilter=n.dataset.filter,renderContent()})}),document.querySelectorAll(".rank-filter-btn").forEach(n=>{n.addEventListener("click",()=>{rankService=n.dataset.service,renderContent()})}),document.querySelectorAll(".equip-filter-btn").forEach(n=>{n.addEventListener("click",()=>{equipmentFilter=n.dataset.equipFilter||n.dataset.filter,renderContent()})})}document.addEventListener("DOMContentLoaded",()=>{document.getElementById("armed-forces-app").innerHTML='\n        <div id="tab-nav-root"></div>\n        <div id="tab-content-root"></div>\n    ',renderTabNav(),renderContent(),document.getElementById("tab-nav-root").addEventListener("click",n=>{const e=n.target.closest(".tab-btn");e&&(activeTab=e.dataset.tab,renderTabNav(),renderContent())})});